/* * <pwd.h> for OS-9. * * OS-9 has no /etc/passwd: a user is a group.user number pair, and the name * lives in the password file only if the system runs login.  This declares * just the shape the shim in shims/os9getpw.c fills in, which is all any * program on this disk actually reads. */struct passwd {    char *pw_name;    char *pw_passwd;    int   pw_uid;    int   pw_gid;    char *pw_gecos;    char *pw_dir;    char *pw_shell;};struct passwd *getpwuid();struct passwd *getpwnam();